pub fn show(date: PhpDateTime) -> String {
    return format!("{} object", php_date_format(date, "Y-m-d"));
}

pub fn describe(text: &str) -> String {
    let date = parse(text);
    let Some(date) = date else {
        return String::from("false");
    };
    let copy = date;
    return format!("{} {}", show(copy), show(date));
}

pub fn maybe(text: &str) -> Option<PhpDateTime> {
    if text == "" {
        return None;
    }
    return parse(text);
}

pub fn chosen(kind: i64, text: &str) -> Option<PhpDateTime> {
    return match kind {
        1 => parse(text),
        _ => None,
    };
}

pub fn held(text: &str) -> Option<PhpDateTime> {
    let result = false;
    if text != "" {
        return parse(text);
    }
    return {
        let _ = result;
        None
    };
}

pub fn given(date: Option<PhpDateTime>) -> String {
    let Some(date) = date else {
        return String::from("false");
    };
    return php_date_format(date, "Y");
}

pub fn either(text: &str) -> String {
    let date = parse(text);
    return format!(
        "{}{}",
        if date.is_some() { "some" } else { "none" },
        if date.is_none() { " false" } else { " date" }
    );
}

